/* Standalone prototype. All advertisements, balances and receipts are simulated. */
const DEFAULTS = {minRounds:2,maxRounds:4,interval:5,reward:10,unit:'金币',sequence:['interstitial','rewarded','interstitial'],exitPolicy:'keep'};
const STORAGE='tgg-signin-prototype-20261102';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const copy=x=>JSON.parse(JSON.stringify(x));
let cfg=copy(DEFAULTS), run=null, balance=256, scene='home', adIndex=0, priorScene='home', toastTimer;
try {const saved=JSON.parse(localStorage.getItem(STORAGE));if(saved){cfg={...DEFAULTS,...saved.cfg};balance=saved.balance??256;run=saved.run?.date===today()?saved.run:null;}}catch{}
// Confirmed rules supersede previously selectable prototype variants.
cfg.unit='金币';cfg.exitPolicy='keep';
// Old fixed-round settings migrate to the new example range; existing runs keep their target.
delete cfg.rounds;
if(run?.config){run.config.unit='金币';run.config.exitPolicy='keep';}
const $=s=>document.querySelector(s);
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const active=()=>run?.config||cfg;
const completed=()=>run?.completed||0;
const remaining=()=>Math.max(0,Math.ceil(((run?.nextAt||0)-Date.now())/1000));
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({cfg,run,balance}));}catch{}}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function sampleConfig(){return {...copy(cfg),rounds:cfg.minRounds+Math.floor(Math.random()*(cfg.maxRounds-cfg.minRounds+1))};}
function ensureRun(){if(run?.date!==today())run=null;if(!run)run={date:today(),config:sampleConfig(),completed:0,claimed:false,nextAt:0,claimPending:false};persist();}
function chips(c){return c.sequence.map(type=>`<span>${type==='rewarded'?'激励视频':'插屏'}</span>`).join(' → ');}
function homeHTML(r=run,c=r?.config||cfg){const done=r?.completed||0,claimed=r?.claimed;return `<div class="page-content"><div class="banner"><div><span class="ad-label">横幅广告 · 示意</span><b>发现日常的小美好</b><p>新鲜生活，每天多一点期待</p></div><div class="leaf-art">❧</div></div><div class="welcome"><div><h2>今天，也有收获。</h2><p>完成签到，领取固定奖励</p></div><span class="date-label">每日签到</span></div><div class="reward-card"><div class="overline">${claimed?'今日奖励已到账':'今日签到奖励'}</div><div class="coin">鹿</div><div class="reward-number">${claimed?'+':''}${c.reward}<span>${escapeHTML(c.unit)}</span></div><p>${claimed?'今日签到已完成，明天再来':done?`已完成 ${done}/${c.rounds} 轮，继续领取今日奖励`:r?`本次共 ${c.rounds} 轮，每轮完成一组广告后记录进度`:`每次随机 ${c.minRounds}～${c.maxRounds} 轮，开始后确定本次轮数`}</p><button class="primary" data-action="open" ${claimed?'disabled':''}>${claimed?'今日已签到':r?.claimPending?'查询奖励结果':done===c.rounds?'完成签到':done?'继续签到':'立即签到'}</button><div class="fine">${c.exitPolicy==='keep'?'已完成轮数自动保留':'未领奖时退出将重新开始'} · 每日领取一次</div></div><div class="rule-list"><span>✓ 固定奖励</span><span>✓ 无抽奖</span><span>✓ 无盲盒</span></div><div class="feed-card"><div class="feed-art">❧</div><div><span class="ad-label">信息流广告 · 示意</span><b>把好心情，带进每一天</b><p>广告展示不计入签到轮数</p></div></div><div class="bottom-banner">底部横幅广告展示区 · 示意</div></div>`;}
function dots(r,c){return `<div class="progress-dots">${Array.from({length:c.rounds},(_,i)=>`<span class="round-dot ${i<r.completed?'done':i===r.completed?'current':''}">${i<r.completed?'✓':i+1}</span>`).join('')}</div>`;}
function progressHTML(r=run,c=r?.config||cfg){const n=r?.completed||0,ready=n>=c.rounds,cooldown=remaining();return `<div class="veil"><section class="dialog" role="dialog" aria-modal="true" aria-label="签到进度"><div class="top-icon">${ready?'✓':'☀'}</div><h2>${ready?'轮次已完成，领取奖励吧':'距离今天的奖励更近一步'}</h2><p class="sub">${ready?`点击完成签到，领取 ${c.reward} ${escapeHTML(c.unit)}`:`本次签到需要完成 ${c.rounds} 轮<br>每次点击“获取”，开始一组广告`}</p>${dots({completed:n},c)}<div class="progress-track"><i style="width:${100*n/c.rounds}%"></i></div><div class="progress-copy"><span>已完成 ${n} / ${c.rounds} 轮</span><span>${ready?'等待领取':`剩余 ${c.rounds-n} 轮`}</span></div><div class="group-note">${ready?'奖励固定发放，无需抽奖或开启盲盒':`每轮顺序：${c.sequence.map(t=>t==='rewarded'?'激励':'插屏').join(' → ')}<br>完整完成一组后，计入一轮进度`}</div><button class="primary" data-action="${ready?'claim':'get'}" ${!ready&&cooldown?'disabled':''}>${ready?'完成签到':cooldown?`${cooldown} 秒后继续获取`:`获取 · 第 ${n+1} 轮`}</button><button class="text-button" data-action="exit">稍后继续</button></section></div>`;}
function adHTML(r=run,c=active(),index=adIndex){const type=c.sequence[index],name=type==='rewarded'?'激励视频':'插屏广告';return `<div class="ad-screen"><div class="ad-top"><span>第 ${r.completed+1} / ${c.rounds} 轮</span><button class="ad-close" data-action="exit">退出 ×</button></div><div class="ad-creative"><span class="ad-label">${name} · 原型模拟</span><div class="illustration">❧</div><h2>生活有新意<br>每天有期待</h2><p>此处由广告组件展示内容<br>无真实广告请求与收益</p></div><div class="ad-progress"><b>${name} · 组内第 ${index+1} / ${c.sequence.length} 步</b><div class="sequence-chips" style="margin:12px 0 0">${chips(c)}</div><small>${type==='rewarded'?'完整观看激励视频后，才能继续本轮。提前关闭不计为完成。':'此为广告组件示意。实际展示、关闭与频次由平台能力决定。'}</small></div><div class="ad-actions"><button class="primary" data-action="adComplete">${type==='rewarded'?'模拟完整观看':'模拟展示并关闭'}</button><button data-action="adFail">模拟加载失败</button></div><p class="fine">只有完整完成本组 ${c.sequence.length} 步，才会增加已完成轮数。</p></div>`;}
function exitHTML(r=run,c=active()){return `<div class="veil"><section class="dialog" role="dialog" aria-modal="true" aria-label="退出确认"><div class="top-icon warning-icon">↗</div><h2>${c.exitPolicy==='keep'?'要暂时离开签到吗？':'退出则重新签到'}</h2><p class="sub">${c.exitPolicy==='keep'?'已完成轮数将保留，本轮需重新完成。':'确认退出将清空本次未领奖的签到进度。'}</p><div class="exit-detail">已完成：${r?.completed||0} / ${c.rounds} 轮<br>${c.exitPolicy==='keep'?'再次进入后，可从下一轮继续签到。':'再次进入后，需要从第 1 轮重新开始。'}<br>尚未领取奖励，不会扣除已有${escapeHTML(c.unit)}。</div><div class="dialog-actions"><button class="secondary" data-action="cancelExit">取消</button><button class="primary" data-action="confirmExit">确定退出</button></div></section></div>`;}
function resultHTML(kind,r=run,c=active()){if(kind==='success')return `<div class="veil"><section class="dialog" role="dialog" aria-modal="true" aria-label="签到成功"><div class="success-mark">✓</div><h2>签到成功，奖励已到账</h2><p class="sub">今天的坚持，收获一份小奖励</p><div class="reward-number">+${c.reward}<span>${escapeHTML(c.unit)}</span></div><div class="receipt"><span>每日签到 · 固定奖励</span><span>已到账</span></div><p class="balance-line">模拟余额 <strong>${r===run?balance:256+c.reward}</strong> ${escapeHTML(c.unit)}</p><button class="primary" data-action="backHome">返回签到首页</button><p class="fine">今日已领取，明天再来。重复点击不会重复发奖。</p></section></div>`;
 if(kind==='uncertain')return `<div class="veil"><section class="dialog" role="dialog" aria-modal="true" aria-label="奖励确认中"><div class="top-icon">↻</div><h2>奖励结果确认中</h2><p class="sub">所有轮次已完成，进度已保留。<br>暂未收到到账结果，请查询后确认。</p><div class="group-note">待核对奖励：${c.reward} ${escapeHTML(c.unit)}<br>无需重新观看广告，不要重复提交领取。</div><button class="primary" data-action="queryReward">查询奖励结果</button><button class="text-button" data-action="backHome">稍后查看</button></section></div>`;
 return `<div class="veil"><section class="dialog" role="dialog" aria-modal="true" aria-label="广告未完成"><div class="top-icon warning-icon">!</div><h2>本轮暂未完成</h2><p class="sub">广告未能完整展示或观看。<br>已完成的 ${completed()} 轮仍然保留。</p><div class="group-note">本轮未计入进度，不会扣除已有奖励。<br>稍后可重新获取本轮。</div><button class="primary" data-action="retryAd">重试本轮</button><button class="text-button" data-action="exit">稍后继续</button></section></div>`;
}
function render(){if(run?.date!==today())run=null;const c=active();$('.intro').textContent=c.exitPolicy==='keep'?'签到 → 逐轮获取 → 完成签到 → 奖励到账。退出后保留已完成轮数，让进度看得见。':'签到 → 逐轮获取 → 完成签到 → 奖励到账。本方案在未领奖时确认退出，会清空本次进度。';$('.unit').textContent=c.unit;
 $('#screen').innerHTML=scene==='ad'?adHTML():homeHTML()+(scene==='progress'||scene==='ready'?progressHTML():scene==='exit'?exitHTML():['success','error','uncertain'].includes(scene)?resultHTML(scene):'');
 document.querySelectorAll('[data-scene]').forEach(b=>b.classList.toggle('active',b.dataset.scene===scene));$('#sequenceChips').innerHTML=chips(cfg);
}
function open(){ensureRun();if(run.claimed)return;scene=run.claimPending?'uncertain':completed()>=active().rounds?'ready':'progress';render();}
function exit(){if(!run||run.claimed||run.claimPending){scene='home';render();return;}priorScene=scene;scene='exit';render();}
function claim(){if(!run||completed()<active().rounds||run.claimed||run.claimPending)return;run.claimPending=true;persist();scene='uncertain';render();setTimeout(()=>{if(run?.claimPending&&scene==='uncertain')settle();},700);}
function settle(){if(!run||run.claimed||completed()<active().rounds)return;balance+=active().reward;run.claimed=true;run.claimPending=false;persist();scene='success';render();}
function action(name){switch(name){case'open':open();break;case'get':ensureRun();if(remaining()||run.claimed||run.claimPending||completed()>=active().rounds)return;adIndex=0;scene='ad';render();break;case'adComplete':if(scene!=='ad'||!run)return;adIndex++;if(adIndex>=active().sequence.length){run.completed++;run.nextAt=Date.now()+active().interval*1000;adIndex=0;persist();scene=completed()>=active().rounds?'ready':'progress';}render();break;case'adFail':scene='error';adIndex=0;render();break;case'retryAd':scene='progress';render();break;case'exit':exit();break;case'cancelExit':scene=priorScene;render();break;case'confirmExit':if(run&&!run.claimed&&!run.claimPending&&active().exitPolicy==='reset')run=null;adIndex=0;scene='home';persist();render();break;case'claim':claim();break;case'queryReward':settle();break;case'backHome':scene='home';render();break;}}
$('#screen').addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(button&&!button.disabled)action(button.dataset.action);});$('#backButton').onclick=exit;
function preview(name){if(name==='home'){run=null;scene='home';persist();render();return;}const sampled=sampleConfig();run={date:today(),config:sampled,completed:['ready','success'].includes(name)?sampled.rounds:Math.min(1,sampled.rounds-1),claimed:name==='success',nextAt:0,claimPending:false};balance=256+(name==='success'?cfg.reward:0);adIndex=name==='ad'?Math.min(1,cfg.sequence.length-1):0;priorScene='progress';scene=name;persist();render();}
document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>preview(b.dataset.scene));
$('#settings').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);const next={minRounds:Number(data.get('minRounds')),maxRounds:Number(data.get('maxRounds')),interval:Number(data.get('interval')),reward:Number(data.get('reward')),unit:'金币',sequence:data.get('sequence').split(','),exitPolicy:'keep'};if(![next.minRounds,next.maxRounds,next.interval,next.reward].every(Number.isInteger))return notify('请填写整数配置');if(next.minRounds<1||next.maxRounds>10||next.minRounds>next.maxRounds)return notify('轮数范围须为 1～10，最少轮数不能大于最多轮数');if(next.interval<0||next.interval>300||next.reward<1||next.reward>100000)return notify('请检查间隔和奖励范围');cfg=next;persist();$('#configMessage').textContent=run?'已保存。当前签到保留原规则；重置演示后体验新配置。':'已保存，新签到将使用这组配置。';render();};
function formSync(){for(const [key,value]of Object.entries(cfg)){const field=$('#settings').elements.namedItem(key);if(field)field.value=Array.isArray(value)?value.join(','):value;}$('#sequenceChips').innerHTML=chips(cfg);}
$('#failAd').onclick=()=>{ensureRun();if(run.claimed||run.claimPending||completed()>=active().rounds)return notify('请先重置演示，再体验广告失败');scene='error';render();};
$('#uncertainReward').onclick=()=>{if(run?.claimed)return notify('本次奖励已经到账，请先重置演示');ensureRun();run.completed=active().rounds;run.claimPending=true;persist();scene='uncertain';render();};
$('#resetDemo').onclick=()=>{run=null;balance=256;adIndex=0;scene='home';persist();$('#configMessage').textContent='演示已重置，下次签到使用当前配置。';render();notify('演示数据已重置');};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&scene==='ad'){adIndex=0;if(active().exitPolicy==='reset')run=null;persist();scene=run?'progress':'home';}if(!document.hidden)render();});
setInterval(()=>{if(scene==='progress'&&run&&!run.claimed)render();},1000);
function buildOverview(){const c={...copy(DEFAULTS),rounds:3},r={date:today(),config:c,completed:1,claimed:false};const entries=[['01 / 签到首页','横幅与信息流只做展示，点击签到打开轮次弹窗。',homeHTML(null,c)],['02 / 获取轮次','展示总轮数、已完成轮数；间隔结束后可继续获取。',homeHTML(r,c)+progressHTML(r,c)],['03 / 一组广告','按顺序完成插屏、激励、插屏，完成整组才计入一轮。',adHTML(r,c,1)],['04 / 中途退出','取消则继续；确认退出保留已完成轮数，本轮重新开始。',homeHTML(r,c)+exitHTML(r,c)],['05 / 完成签到','全部轮次完成，获取按钮改为“完成签到”。',homeHTML({...r,completed:3},c)+progressHTML({...r,completed:3},c)],['06 / 奖励到账','固定奖励一次发放，今日已签到，重复进入不会重发。',homeHTML({...r,completed:3,claimed:true},c)+resultHTML('success',{...r,claimed:true},c)]];$('#storyboard').innerHTML=entries.map(([title,caption,html])=>`<article class="story-item"><h3>${title}</h3><div class="mini-device">${html}</div><p class="story-caption">${caption}</p></article>`).join('');}
let overview=new URLSearchParams(location.search).has('overview');function toggleOverview(){overview=!overview;updateOverview();}function updateOverview(){$('#workspace').hidden=overview;$('#overview').hidden=!overview;$('#overviewToggle').textContent=overview?'返回交互体验 ↗':'查看流程总览 ↗';if(overview)buildOverview();}
$('#overviewToggle').onclick=toggleOverview;formSync();render();updateOverview();
